INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'formulaire-3916-bis-compte-etranger',(SELECT `id` FROM `blog_categories` WHERE `slug`='finance' LIMIT 1),'Déclarer un compte crypto à l\'étranger : le formulaire 3916 bis','L\'obligation la plus ignorée, la plus simple à remplir, et celle dont l\'oubli coûte le plus cher.','<p>C\'est l\'obligation la plus ignorée, et l\'une des plus simples à remplir. Elle ne dépend ni de vos gains, ni de vos ventes, ni d\'aucun seuil.</p>\n\n<p class=\"wt-note\"><em>Informations générales, à jour à la date de publication. Seules les indications de l\'administration fiscale font foi pour votre situation.</em></p>\n\n<h2>De quoi il s\'agit</h2>\n\n<p>Si vous détenez un compte d\'actifs numériques ouvert, détenu, utilisé ou clos auprès d\'un service établi hors de France, ce compte doit être déclaré chaque année. Le formulaire prévu à cet effet est le 3916-bis, annexé à votre déclaration de revenus.</p>\n\n<p>Un formulaire par compte. Trois comptes chez trois services différents font trois formulaires.</p>\n\n<h2>Pourquoi tant de gens l\'ignorent</h2>\n\n<p>Parce qu\'elle ne ressemble à rien de ce qu\'on associe habituellement aux impôts.</p>\n\n<p>Elle ne dépend pas d\'un gain : vous devez déclarer même si votre compte est vide et n\'a jamais servi. Elle ne dépend pas d\'une vente : conserver sans rien faire ne vous en dispense pas. Elle ne dépend d\'aucun seuil : le fameux plafond de 305 euros n\'a strictement aucun effet ici.</p>\n\n<p>Et elle s\'applique même à un compte clos en cours d\'année. Fermer un compte en mars n\'efface pas l\'obligation de le déclarer au printemps suivant.</p>\n\n<h2>Quels comptes sont concernés</h2>\n\n<p>Les plateformes d\'échange établies à l\'étranger, ce qui représente la grande majorité d\'entre elles. Les microwallets, très courants dans l\'univers des micro-gains. Tout service qui détient des actifs numériques pour votre compte et qui n\'est pas établi en France.</p>\n\n<p>En cas de doute sur le lieu d\'établissement, regardez les mentions légales du service : elles indiquent le pays de la société.</p>\n\n<h2>Ce qui n\'est pas concerné</h2>\n\n<p>Un portefeuille dont vous détenez seules les clés — une application sur votre téléphone, un portefeuille matériel, une phrase de récupération notée sur papier — n\'est pas un compte ouvert auprès d\'un tiers.</p>\n\n<p>La distinction est celle-ci : un tiers détient-il vos fonds pour vous ? Si oui, c\'est un compte. Si vous seul détenez les clés, ce n\'en est pas un.</p>\n\n<h2>Ce qu\'il faut renseigner</h2>\n\n<p>Les informations demandées sont administratives et sans difficulté : la désignation du compte, l\'identité du gestionnaire, son adresse, la date d\'ouverture, et le cas échéant la date de clôture.</p>\n\n<p>Aucun montant, aucun solde, aucun calcul. C\'est une déclaration d\'existence, pas une déclaration de valeur — ce qui la rend beaucoup moins lourde que sa réputation ne le laisse croire.</p>\n\n<h2>Pourquoi ne pas l\'oublier</h2>\n\n<p>Le défaut de déclaration d\'un compte à l\'étranger est sanctionné par une amende, appliquée par compte non déclaré et par année. Le montant est sans commune mesure avec les sommes en jeu sur une plateforme de micro-gains.</p>\n\n<p>C\'est la principale raison d\'en parler : ici, le risque ne vient pas de vos gains, qui sont modestes, mais d\'une formalité oubliée qui coûte bien plus cher que ce qu\'elle concerne.</p>\n\n<h2>La bonne habitude</h2>\n\n<p>Tenez une liste de vos comptes : le nom du service, le pays d\'établissement, la date d\'ouverture. Mettez-la à jour dès que vous en ouvrez ou fermez un.</p>\n\n<p>Au moment de la déclaration, vous n\'aurez qu\'à recopier. Sans cette liste, il faut se souvenir de tous les services essayés dans l\'année — et c\'est précisément là que les oublis se produisent.</p>\n\n<h2>En cas de doute</h2>\n\n<p>Cette obligation est technique et sa formulation évolue. Si votre situation sort du cas simple, la question se pose à votre centre des finances publiques ou à un professionnel. Un article ne peut pas remplacer cet avis, et sur ce sujet précis l\'approximation coûte cher.</p>\n','🌍','Équipe Wintaskly','Déclarer un compte crypto à l\'étranger : le formulaire 3916 bis','L\'obligation la plus ignorée, la plus simple à remplir, et celle dont l\'oubli coûte le plus cher.','published',7,'2026-10-20 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='formulaire-3916-bis-compte-etranger'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'batterie-session-micro-taches',(SELECT `id` FROM `blog_categories` WHERE `slug`='astuces' LIMIT 1),'Faire durer sa batterie pendant une session de micro-tâches','Pourquoi ça consomme, les réglages qui changent vraiment, et les trois faux bons réflexes.','<p>Une session de micro-tâches vide la batterie plus vite qu\'on ne l\'imagine. Sur un téléphone, cela peut suffire à décourager la routine quotidienne. Voici pourquoi, et comment y remédier.</p>\n\n<h2>Pourquoi ça consomme autant</h2>\n\n<p>Ce n\'est pas la plateforme qui pèse, mais ce qui se charge autour.</p>\n\n<p>Les pages sponsorisées appellent plusieurs serveurs distants, exécutent des scripts, affichent parfois des vidéos et des animations. Chacun de ces éléments réveille le processeur et la puce réseau — les deux plus gros consommateurs d\'un téléphone après l\'écran.</p>\n\n<p>S\'y ajoutent les temps d\'attente : pendant une minute de compte à rebours, l\'écran reste allumé à ne rien faire d\'utile.</p>\n\n<h2>Les réglages qui changent le plus</h2>\n\n<p><strong>Baissez la luminosité.</strong> C\'est de loin le premier poste de consommation. Sur une session de vingt minutes, passer de la luminosité maximale à un niveau moyen change davantage que tout le reste réuni.</p>\n\n<p><strong>Activez le thème sombre.</strong> Sur un écran OLED — la plupart des téléphones récents — les pixels noirs sont éteints. Sur nos pages, l\'économie est réelle.</p>\n\n<p><strong>Réduisez le délai de veille.</strong> Trente secondes suffisent. Les pages continuent de charger pendant que l\'écran s\'éteint.</p>\n\n<p><strong>Coupez la 5G si vous êtes en Wi-Fi.</strong> Une puce qui cherche un réseau qu\'elle n\'utilise pas consomme pour rien.</p>\n\n<h2>Ce qu\'il ne faut pas faire</h2>\n\n<p><strong>Le mode économie d\'énergie pendant une tâche.</strong> C\'est contre-intuitif, mais ce mode limite l\'activité en arrière-plan et peut interrompre le chargement d\'une page sponsorisée. Vous économisez trois pour cent de batterie et vous perdez la tâche.</p>\n\n<p><strong>Changer d\'application en cours de parcours.</strong> Le système peut décharger l\'onglet en arrière-plan pour libérer de la mémoire. Au retour, le parcours est cassé et le rechargement consomme davantage que si vous étiez resté.</p>\n\n<p><strong>Ouvrir plusieurs onglets.</strong> Chacun continue de charger et d\'exécuter du code. Trois onglets consomment trois fois plus, pour aucun gain de temps.</p>\n\n<h2>Organiser sa session autrement</h2>\n\n<p>Le meilleur levier n\'est pas un réglage, c\'est le moment choisi.</p>\n\n<p>Faites votre session <strong>pendant que vous chargez</strong> : le matin au petit-déjeuner, le soir avant de dormir. La question de la batterie disparaît entièrement.</p>\n\n<p>À défaut, groupez : une session de vingt minutes coûte moins qu\'un même temps réparti en cinq passages, parce que chaque réveil de l\'appareil et chaque rechargement de page ont un coût fixe.</p>\n\n<h2>Le cas de la connexion mobile</h2>\n\n<p>Si vous êtes en données mobiles, deux effets s\'additionnent : la consommation de batterie liée à la radio, et celle de votre forfait.</p>\n\n<p>Les pages sponsorisées sont les plus lourdes, particulièrement celles qui affichent de la vidéo. Si votre forfait est limité, privilégiez le faucet et le PTC, nettement plus légers, et gardez les parcours complets pour le Wi-Fi.</p>\n\n<h2>Un mot sur la chaleur</h2>\n\n<p>Un téléphone qui chauffe pendant une session ne va pas bien. La chaleur vient d\'un processeur qui travaille en continu — souvent une page mal conçue, avec une vidéo ou une animation qui tourne en boucle.</p>\n\n<p>Si cela se produit systématiquement sur un type de tâche, fermez et passez à autre chose. Une batterie qui chauffe régulièrement vieillit plus vite, et aucun gain de micro-tâches ne compense le remplacement d\'un téléphone.</p>\n','🔋','Équipe Wintaskly','Faire durer sa batterie pendant une session de micro-tâches','Pourquoi ça consomme, les réglages qui changent vraiment, et les trois faux bons réflexes.','published',6,'2026-10-21 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='batterie-session-micro-taches'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'adresse-publique-et-cle-privee',(SELECT `id` FROM `blog_categories` WHERE `slug`='crypto' LIMIT 1),'Adresse publique et clé privée : la différence qui protège votre argent','Ce qui se partage sans risque, ce qui ne se partage jamais, et pourquoi il n\'y a aucun recours.','<p>Deux notions suffisent à comprendre la sécurité d\'un portefeuille crypto : l\'adresse publique et la clé privée. Les confondre est l\'erreur qui coûte le plus cher.</p>\n\n<h2>L\'analogie qui fonctionne</h2>\n\n<p>L\'adresse publique est votre numéro de compte : vous le donnez à qui doit vous payer. La clé privée est la signature qui autorise les paiements sortants.</p>\n\n<p>La différence essentielle avec une banque : personne ne peut regénérer votre signature. Ni un conseiller, ni un support, ni le réseau. Il n\'y a pas d\'autorité au-dessus.</p>\n\n<h2>L\'adresse publique</h2>\n\n<p>Une longue suite de lettres et de chiffres, propre à chaque réseau. Elle sert uniquement à recevoir.</p>\n\n<p>La partager ne présente aucun risque financier : quiconque la connaît peut vous envoyer des fonds, jamais en retirer. C\'est celle que vous saisissez dans vos méthodes de retrait.</p>\n\n<p>Une nuance sur la vie privée, en revanche : une adresse rend consultable tout ce qui y transite. Toute personne la connaissant peut voir votre solde et vos mouvements. Ce n\'est pas un danger pour vos fonds, mais c\'est une information que vous donnez.</p>\n\n<h2>La clé privée</h2>\n\n<p>C\'est elle qui permet de dépenser. Qui la détient contrôle les fonds, entièrement et sans recours.</p>\n\n<p>Trois conséquences qui n\'ont pas d\'équivalent bancaire :</p>\n\n<ul>\n  <li><strong>Personne ne peut la récupérer pour vous.</strong> Perdue, les fonds sont inaccessibles à jamais — ils existent toujours sur la chaîne, mais plus personne ne peut les bouger.</li>\n  <li><strong>Personne ne peut annuler une transaction signée.</strong> Un envoi confirmé est définitif.</li>\n  <li><strong>Personne n\'a besoin de la connaître.</strong> Aucun service légitime, jamais.</li>\n</ul>\n\n<h2>La phrase de récupération</h2>\n\n<p>En pratique, vous ne manipulez pas directement votre clé privée. Vous manipulez une phrase de récupération : une douzaine de mots, générés à la création du portefeuille, dont toutes vos clés sont dérivées.</p>\n\n<p>Cette phrase <em>est</em> votre portefeuille. La détenir, c\'est détenir les fonds — sur n\'importe quel appareil, sans mot de passe, sans autre vérification.</p>\n\n<p>C\'est pourquoi toutes les escroqueries convergent vers elle. Un faux support, un faux formulaire de vérification, une fausse application de sauvegarde : l\'objectif est toujours le même.</p>\n\n<h2>Ce qui est sûr et ce qui ne l\'est pas</h2>\n\n<table>\n  <tr><th>Élément</th><th>Peut être partagé</th></tr>\n  <tr><td>Adresse publique</td><td>Oui, sans risque financier</td></tr>\n  <tr><td>Identifiant de transaction</td><td>Oui</td></tr>\n  <tr><td>Clé privée</td><td>Jamais</td></tr>\n  <tr><td>Phrase de récupération</td><td>Jamais</td></tr>\n</table>\n\n<h2>Le cas des comptes hébergés</h2>\n\n<p>Sur un microwallet ou une plateforme d\'échange, vous n\'avez ni clé privée ni phrase de récupération. Le service les détient pour vous, et vous accédez à votre solde par un identifiant et un mot de passe.</p>\n\n<p>Cela change tout : vous pouvez récupérer un accès perdu, mais vous dépendez entièrement du service. La formule consacrée le résume — sans les clés, ce ne sont pas vraiment vos fonds.</p>\n\n<p>Ce n\'est pas un défaut en soi. C\'est un compromis adapté aux petits montants en transit, et bien moins adapté à une conservation longue.</p>\n\n<h2>Les réflexes qui suffisent</h2>\n\n<ul>\n  <li>Copiez toujours votre adresse, ne la retapez jamais.</li>\n  <li>Relisez après avoir collé : certains programmes malveillants remplacent le presse-papiers.</li>\n  <li>Notez votre phrase de récupération sur papier, en deux exemplaires, à deux endroits.</li>\n  <li>Ne la photographiez jamais, ne la stockez dans aucun fichier synchronisé.</li>\n  <li>Considérez comme escroquerie toute demande de cette phrase, sans exception.</li>\n</ul>\n','🔑','Équipe Wintaskly','Adresse publique et clé privée : la différence qui protège votre argent','Ce qui se partage sans risque, ce qui ne se partage jamais, et pourquoi il n\'y a aucun recours.','published',6,'2026-10-22 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='adresse-publique-et-cle-privee'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'economiser-donnees-mobiles',(SELECT `id` FROM `blog_categories` WHERE `slug`='astuces' LIMIT 1),'Économiser ses données mobiles sur les pages sponsorisées','Où passent vraiment vos mégaoctets, et le piège du bloqueur qui économise pour un gain nul.','<p>Sur un forfait limité, quelques sessions quotidiennes peuvent peser lourd. Voici où passent vos données, et comment réduire la facture sans perdre de tâches.</p>\n\n<h2>Où passent réellement les données</h2>\n\n<p>Ce n\'est pas la plateforme qui consomme — nos pages sont légères. Ce sont les pages sponsorisées, et surtout ce qu\'elles chargent.</p>\n\n<p>Par ordre de poids : les vidéos publicitaires, de loin les plus gourmandes ; les images en haute définition ; les scripts de suivi, nombreux et parfois redondants ; enfin les polices d\'écriture chargées à distance.</p>\n\n<p>Une page sponsorisée chargée de vidéo peut consommer autant qu\'une dizaine de pages ordinaires.</p>\n\n<h2>Choisir les tâches les plus légères</h2>\n\n<p>C\'est le levier le plus efficace, et personne n\'en parle.</p>\n\n<p>Le <strong>faucet</strong> et le <strong>PTC</strong> chargent peu : quelques éléments, pas de vidéo. Le bonus quotidien ne consomme presque rien.</p>\n\n<p>Les <strong>parcours de liens sponsorisés</strong> sont les plus lourds, puisqu\'ils enchaînent plusieurs pages, chacune avec ses propres publicités. Les <strong>murs d\'offres</strong> peuvent l\'être aussi, surtout s\'ils demandent d\'installer une application.</p>\n\n<p>Si votre forfait est serré, la stratégie est claire : faucet, PTC et bonus en données mobiles ; les parcours complets et les offres, uniquement en Wi-Fi.</p>\n\n<h2>Les réglages du navigateur</h2>\n\n<p><strong>Coupez la lecture automatique des vidéos.</strong> La plupart des navigateurs mobiles proposent ce réglage. C\'est la plus grosse économie possible en un seul geste.</p>\n\n<p><strong>Activez le mode économiseur de données</strong> s\'il existe dans votre navigateur. Il compresse les images et bloque certains chargements automatiques.</p>\n\n<p><strong>Ne coupez pas les images entièrement.</strong> C\'est tentant, mais une bannière qui ne se charge pas n\'est pas comptée : vous risquez d\'invalider la tâche pour économiser quelques kilo-octets.</p>\n\n<h2>Le piège du bloqueur</h2>\n\n<p>Bloquer les publicités semble être la solution idéale pour économiser des données. C\'est effectivement efficace — et c\'est exactement ce qui empêche vos tâches d\'être créditées.</p>\n\n<p>Sans affichage, l\'intermédiaire ne compte rien, nous ne recevons rien, et vous n\'êtes pas payé. Vous auriez économisé des données pour un gain nul.</p>\n\n<p>Le compromis raisonnable : coupez les vidéos, gardez les images.</p>\n\n<h2>Suivre sa consommation</h2>\n\n<p>Les téléphones proposent un suivi par application dans les réglages réseau. Regardez ce que consomme votre navigateur sur une semaine, et divisez par le nombre de sessions.</p>\n\n<p>Ce chiffre vous donnera une base réelle. Certains découvrent qu\'une session leur coûte quelques mégaoctets, d\'autres bien davantage — cela dépend entièrement des annonceurs diffusés dans votre pays.</p>\n\n<h2>Organiser autrement</h2>\n\n<p>La solution la plus simple reste de déplacer la session. Si vous avez du Wi-Fi le matin ou le soir, faites-y vos parcours complets et gardez les tâches légères pour la journée.</p>\n\n<p>Le bonus quotidien, lui, peut se réclamer n\'importe où : il ne consomme presque rien et c\'est celui qu\'il ne faut jamais rater.</p>\n\n<h2>La question à se poser</h2>\n\n<p>Soyons concrets. Si une session vous coûte davantage en données que ce qu\'elle rapporte, elle n\'a pas de sens.</p>\n\n<p>Faites le calcul une fois : consommation par session, coût de vos données, gain moyen. Si le rapport n\'est pas nettement favorable, limitez-vous aux tâches légères et au Wi-Fi. C\'est une réponse honnête, même si elle réduit l\'usage de la plateforme.</p>\n','📶','Équipe Wintaskly','Économiser ses données mobiles sur les pages sponsorisées','Où passent vraiment vos mégaoctets, et le piège du bloqueur qui économise pour un gain nul.','published',6,'2026-10-23 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='economiser-donnees-mobiles'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'flat-tax-ou-bareme-progressif',(SELECT `id` FROM `blog_categories` WHERE `slug`='finance' LIMIT 1),'Flat tax ou barème progressif : comment choisir','Le régime par défaut n\'est pas le plus favorable pour beaucoup. Le calcul de décision en une ligne.','<p>Face aux plus-values sur actifs numériques, deux régimes s\'offrent à vous. L\'un s\'applique par défaut, l\'autre sur option. Le bon choix dépend d\'un seul chiffre : votre taux marginal d\'imposition.</p>\n\n<p class=\"wt-note\"><em>Informations générales, à jour à la date de publication. Seules les indications de l\'administration fiscale font foi pour votre situation.</em></p>\n\n<h2>Le régime par défaut</h2>\n\n<p>Le prélèvement forfaitaire unique s\'applique automatiquement. Depuis le 1er janvier 2026, son taux global est de <strong>31,4 %</strong> : 12,8 % d\'impôt sur le revenu et 18,6 % de prélèvements sociaux.</p>\n\n<p>Il était de 30 % auparavant. La hausse vient entièrement des prélèvements sociaux, portés de 17,2 % à 18,6 % par la loi de financement de la sécurité sociale pour 2026.</p>\n\n<p>Son avantage est la simplicité : un taux unique, quel que soit votre revenu par ailleurs.</p>\n\n<h2>L\'option pour le barème progressif</h2>\n\n<p>Vous pouvez renoncer au taux forfaitaire et intégrer vos plus-values à votre revenu imposable ordinaire. Elles sont alors soumises à votre tranche marginale, plus les prélèvements sociaux.</p>\n\n<p>Deux points à connaître avant de choisir.</p>\n\n<p><strong>Les prélèvements sociaux restent dus dans les deux cas</strong>, au même taux. L\'option ne joue que sur la part d\'impôt sur le revenu.</p>\n\n<p><strong>L\'option est globale.</strong> Elle s\'applique à l\'ensemble de vos revenus du capital de l\'année, pas seulement à vos crypto-actifs. Si vous percevez aussi des dividendes ou des intérêts, tout bascule ensemble.</p>\n\n<h2>Le calcul de décision</h2>\n\n<p>Comparez simplement votre tranche marginale à 12,8 %.</p>\n\n<ul>\n  <li><strong>Tranche à 0 %</strong> — vous n\'êtes pas imposable : le barème est nettement plus avantageux. Vous ne payez alors que les prélèvements sociaux, au lieu de 31,4 %.</li>\n  <li><strong>Tranche à 11 %</strong> — le barème reste généralement plus favorable, l\'écart avec 12,8 % jouant en sa faveur.</li>\n  <li><strong>Tranche à 30 % ou plus</strong> — le forfait est plus avantageux. Le barème vous ferait payer davantage sur la part d\'impôt.</li>\n</ul>\n\n<p>Le seuil de bascule se situe donc entre la tranche à 11 % et celle à 30 %.</p>\n\n<h2>Pourquoi cela concerne les micro-gains</h2>\n\n<p>Beaucoup de membres d\'une plateforme de micro-gains ne sont pas imposables, ou le sont dans la première tranche. C\'est précisément la situation où l\'option est intéressante.</p>\n\n<p>Autrement dit : le régime qui s\'applique automatiquement n\'est pas le plus favorable pour une bonne part des gens concernés. Encore faut-il le savoir, car l\'option doit être demandée expressément — elle n\'est jamais appliquée d\'office.</p>\n\n<h2>Comment exercer l\'option</h2>\n\n<p>En cochant la case prévue à cet effet sur votre déclaration de revenus. C\'est une case unique, valable pour l\'ensemble de l\'année.</p>\n\n<p>Un point rassurant : le service de déclaration en ligne calcule généralement les deux hypothèses et signale la plus favorable. Prenez le temps de lire cet écran plutôt que de valider mécaniquement.</p>\n\n<h2>Ce que l\'option ne change pas</h2>\n\n<p>Ni l\'obligation de déclarer vos opérations, ni celle de déclarer un compte détenu à l\'étranger, ni le calcul de la plus-value elle-même. L\'option porte uniquement sur la façon dont le résultat est imposé.</p>\n\n<h2>Le conseil pratique</h2>\n\n<p>Ne décidez pas avant d\'avoir les chiffres. Remplissez d\'abord vos opérations, regardez le résultat, puis comparez les deux hypothèses avec l\'ensemble de vos revenus de l\'année.</p>\n\n<p>Et si vos revenus du capital sont plus variés que quelques retraits crypto, la question mérite un avis professionnel : l\'option étant globale, elle peut être favorable sur un poste et défavorable sur un autre.</p>\n','⚖️','Équipe Wintaskly','Flat tax ou barème progressif : comment choisir','Le régime par défaut n\'est pas le plus favorable pour beaucoup. Le calcul de décision en une ligne.','published',7,'2026-10-26 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='flat-tax-ou-bareme-progressif'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'verifier-transaction-explorateur',(SELECT `id` FROM `blog_categories` WHERE `slug`='crypto' LIMIT 1),'Vérifier une transaction sur un explorateur de blocs','L\'outil qui répond en trente secondes à « où est mon argent ? », sans demander à personne.','<p>Un explorateur de blocs permet de vérifier soi-même où en est une transaction, sans demander à personne. C\'est l\'outil qui répond à la question « où est mon argent ? » en trente secondes.</p>\n\n<h2>Ce que c\'est</h2>\n\n<p>Les réseaux crypto sont publics : toutes les transactions y sont consultables. Un explorateur est simplement un site qui rend ces données lisibles.</p>\n\n<p>Chaque réseau a le sien. Un explorateur Bitcoin ne connaît pas les transactions Tron, et inversement — ce sont des registres différents.</p>\n\n<h2>L\'identifiant de transaction</h2>\n\n<p>Quand un paiement part, il reçoit un identifiant unique : une longue suite de caractères, souvent appelée hash ou TXID.</p>\n\n<p>C\'est votre numéro de suivi. Il figure dans votre historique de retraits une fois la transaction émise. Sans lui, vous ne pouvez rien vérifier ; avec lui, tout.</p>\n\n<h2>Comment procéder</h2>\n\n<ol>\n  <li>Notez l\'identifiant depuis votre historique de retraits.</li>\n  <li>Ouvrez un explorateur correspondant au bon réseau.</li>\n  <li>Collez l\'identifiant dans la barre de recherche.</li>\n  <li>Lisez le statut.</li>\n</ol>\n\n<p>Vous pouvez aussi rechercher une adresse plutôt qu\'une transaction : l\'explorateur affiche alors tous les mouvements de cette adresse.</p>\n\n<h2>Lire le résultat</h2>\n\n<p><strong>« Confirmée » avec un nombre de confirmations.</strong> La transaction est inscrite. Chaque nouveau bloc ajoute une confirmation et la rend plus définitive. Au-delà de quelques confirmations, l\'opération est irréversible.</p>\n\n<p><strong>« En attente » ou « non confirmée ».</strong> Elle a été diffusée mais n\'est pas encore incluse dans un bloc. C\'est normal, surtout si le réseau est chargé ou si les frais choisis étaient bas.</p>\n\n<p><strong>« Introuvable ».</strong> Deux possibilités : la transaction n\'a pas encore été diffusée, ou vous consultez le mauvais réseau. Vérifiez le second point avant de vous inquiéter — c\'est de loin le cas le plus fréquent.</p>\n\n<h2>Ce que cela vous permet de trancher</h2>\n\n<p>Quand un retrait n\'arrive pas, la question est toujours la même : le problème est-il chez l\'expéditeur ou chez le destinataire ?</p>\n\n<p>L\'explorateur y répond sans ambiguïté. Si la transaction est confirmée et que le montant figure à la bonne adresse, les fonds sont arrivés sur la chaîne : le problème se situe chez le service qui reçoit, pas chez celui qui envoie.</p>\n\n<p>À l\'inverse, si aucune transaction n\'existe, elle n\'a pas encore été émise.</p>\n\n<p>C\'est une information objective, vérifiable par vous comme par nous, et elle rend la conversation avec un support beaucoup plus courte.</p>\n\n<h2>Le piège de l\'adresse</h2>\n\n<p>En consultant une transaction, vérifiez que l\'adresse de destination est bien celle que vous aviez enregistrée. Comparez au moins les premiers et les derniers caractères.</p>\n\n<p>Si elle diffère, vous avez probablement saisi une adresse erronée — et c\'est malheureusement irréversible. Mieux vaut le savoir tout de suite que de chercher pendant des jours.</p>\n\n<h2>Ce que l\'explorateur ne montre pas</h2>\n\n<p>Les mouvements internes à un microwallet ou à une plateforme d\'échange n\'apparaissent pas. Ce sont des écritures dans leur propre base, pas des transactions sur la chaîne.</p>\n\n<p>C\'est précisément ce qui les rend gratuites et instantanées. Mais cela signifie qu\'un versement vers un compte hébergé n\'est pas vérifiable de cette façon : seul le service concerné peut vous le confirmer.</p>\n\n<h2>Une remarque sur la vie privée</h2>\n\n<p>Tout ceci fonctionne dans les deux sens. Quiconque connaît une de vos adresses peut voir son solde et son historique complet.</p>\n\n<p>Ce n\'est pas un risque pour vos fonds — une adresse ne permet pas de les dépenser. Mais c\'est une information que vous donnez en même temps que l\'adresse, et il vaut mieux le savoir.</p>\n','🔍','Équipe Wintaskly','Vérifier une transaction sur un explorateur de blocs','L\'outil qui répond en trente secondes à « où est mon argent ? », sans demander à personne.','published',7,'2026-10-27 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='verifier-transaction-explorateur'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'calendrier-fiscal-outre-mer',(SELECT `id` FROM `blog_categories` WHERE `slug`='finance' LIMIT 1),'Calendrier fiscal 2027 : les dates à ne pas manquer outre-mer','Trois zones, et l\'outre-mer dans la dernière. Le piège de la déclaration papier.','<p>Les dates de déclaration ne sont pas les mêmes partout, et l\'outre-mer figure dans la dernière zone. Voici comment fonctionne ce calendrier, et pourquoi il ne faut pas se fier à un article — y compris celui-ci — pour connaître les dates exactes.</p>\n\n<p class=\"wt-note\"><em>Informations générales. Les dates de chaque campagne sont fixées et publiées par l\'administration fiscale : vérifiez-les sur impots.gouv.fr.</em></p>\n\n<h2>Le principe des trois zones</h2>\n\n<p>La déclaration en ligne s\'échelonne selon le département de résidence, réparti en trois zones. L\'objectif est d\'étaler la charge sur les serveurs et les services, pas de favoriser qui que ce soit.</p>\n\n<p>Les départements sont classés par numéro croissant, et <strong>les départements d\'outre-mer, dont La Réunion, se trouvent dans la dernière zone</strong> — celle dont l\'échéance est la plus tardive.</p>\n\n<p>C\'est une bonne nouvelle pratique : vous disposez de plus de temps que la métropole. C\'est aussi un piège, parce que tous les articles que vous croiserez citeront d\'abord les dates de la première zone.</p>\n\n<h2>Les jalons d\'une campagne</h2>\n\n<p>Le déroulé est stable d\'une année sur l\'autre, même si les dates changent :</p>\n\n<ol>\n  <li><strong>Ouverture du service en ligne</strong>, au printemps. C\'est à partir de ce moment que vous pouvez déclarer.</li>\n  <li><strong>Limite pour la déclaration papier</strong>, unique pour tout le monde et plus précoce que les échéances en ligne.</li>\n  <li><strong>Limites en ligne</strong>, échelonnées par zone.</li>\n  <li><strong>Réception de l\'avis d\'impôt</strong>, durant l\'été.</li>\n  <li><strong>Date limite de paiement du solde</strong>, à l\'automne.</li>\n</ol>\n\n<p>Retenez surtout que la déclaration papier a une échéance plus courte que la vôtre en ligne. Si vous déclarez sur papier, votre statut ultramarin ne vous accorde pas de délai supplémentaire.</p>\n\n<h2>Ce qui concerne les gains en ligne</h2>\n\n<p>Trois éléments peuvent vous concerner, et ils se remplissent au même moment :</p>\n\n<ul>\n  <li>le formulaire détaillant vos cessions d\'actifs numériques, s\'il y en a eu ;</li>\n  <li>le report du résultat sur la déclaration complémentaire, en plus-value ou en moins-value ;</li>\n  <li>la déclaration de chaque compte d\'actifs numériques détenu à l\'étranger — obligation indépendante de toute opération.</li>\n</ul>\n\n<p>Cette dernière est celle qu\'on oublie, et son oubli est sanctionné par compte et par année.</p>\n\n<h2>Préparer plutôt que subir</h2>\n\n<p>La difficulté n\'est jamais la déclaration elle-même : c\'est la reconstitution.</p>\n\n<p>Retrouver au printemps le prix d\'acquisition de crypto reçues quatorze mois plus tôt, sur trois services différents, est une corvée — et parfois une impasse. Sans prix d\'acquisition, la plus-value ne peut pas être calculée.</p>\n\n<p>Deux minutes par mois suffisent à l\'éviter. Notez au fil de l\'eau : date, montant, devise, contrepartie en euros, et le service concerné. Une simple feuille de calcul fait l\'affaire.</p>\n\n<h2>Le réflexe pour connaître les vraies dates</h2>\n\n<p>Ne les cherchez pas dans un article. Elles changent chaque année, et les articles ne sont pas mis à jour.</p>\n\n<p>Le calendrier officiel est publié sur impots.gouv.fr avant l\'ouverture de la campagne. C\'est la seule source qui fasse foi, et elle est gratuite et accessible.</p>\n\n<p>Un conseil de méthode : posez un rappel dans votre agenda dès que vous connaissez la date limite de votre zone, une semaine avant l\'échéance. Le service en ligne connaît des ralentissements dans les derniers jours, et ce n\'est pas le moment de découvrir qu\'il vous manque un chiffre.</p>\n','📅','Équipe Wintaskly','Calendrier fiscal 2027 : les dates à ne pas manquer outre-mer','Trois zones, et l\'outre-mer dans la dernière. Le piège de la déclaration papier.','published',6,'2026-10-28 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='calendrier-fiscal-outre-mer'));

INSERT INTO `blog_posts` (`slug`,`category_id`,`title`,`excerpt`,`body`,`cover_emoji`,`author_name`,`meta_title`,`meta_description`,`status`,`reading_minutes`,`published_at`)
SELECT 'raccourci-ecran-accueil',(SELECT `id` FROM `blog_categories` WHERE `slug`='astuces' LIMIT 1),'Un raccourci sur l\'écran d\'accueil pour gagner 30 secondes par jour','Trente secondes par jour font trois heures par an. Et le détail que presque tout le monde manque.','<p>Trente secondes par jour, c\'est trois heures sur un an. Sur une plateforme où l\'on revient tous les jours, réduire le trajet jusqu\'à la session est le seul gain de temps qui se cumule vraiment.</p>\n\n<h2>Ce que vous faites aujourd\'hui</h2>\n\n<p>Déverrouiller, ouvrir le navigateur, chercher l\'onglet ou taper l\'adresse, attendre le chargement, se connecter si la session a expiré, trouver la page des tâches.</p>\n\n<p>Chaque étape prend quelques secondes. Additionnées et répétées quotidiennement, elles représentent une friction réelle — et la friction est ce qui tue les habitudes, bien avant le manque de motivation.</p>\n\n<h2>Le raccourci sur l\'écran d\'accueil</h2>\n\n<p>Tous les navigateurs mobiles permettent d\'ajouter un site à l\'écran d\'accueil. L\'icône se comporte alors comme une application : un appui, et vous y êtes.</p>\n\n<p><strong>Sur Android :</strong> ouvrez le site, touchez le menu du navigateur, choisissez « Ajouter à l\'écran d\'accueil ».</p>\n\n<p><strong>Sur iPhone :</strong> ouvrez le site dans Safari, touchez le bouton de partage, puis « Sur l\'écran d\'accueil ».</p>\n\n<p>Le nom proposé est modifiable : raccourcissez-le pour qu\'il s\'affiche entièrement sous l\'icône.</p>\n\n<h2>Pointer vers la bonne page</h2>\n\n<p>C\'est le détail que presque tout le monde manque, et c\'est lui qui apporte l\'essentiel du gain.</p>\n\n<p>N\'ajoutez pas la page d\'accueil. Ajoutez <strong>la page où commence réellement votre session</strong> — celle du tableau de bord, ou directement celle des tâches. Vous économisez ainsi deux ou trois navigations à chaque fois.</p>\n\n<p>Si vous faites toujours la même chose en premier, allez jusqu\'à cette page précise avant d\'ajouter le raccourci. L\'adresse enregistrée sera celle affichée à ce moment-là.</p>\n\n<h2>Rester connecté</h2>\n\n<p>Rien n\'use plus qu\'une session expirée à chaque visite. Cochez l\'option qui vous maintient connecté, si votre appareil est personnel.</p>\n\n<p>Deux conditions, cependant. Sur un appareil partagé ou emprunté, ne le faites pas. Et activez la double authentification : rester connecté sur un téléphone verrouillé est raisonnable, sur un téléphone sans code d\'accès ne l\'est pas.</p>\n\n<h2>Placez l\'icône là où vous regardez</h2>\n\n<p>Le meilleur emplacement n\'est pas le plus beau, c\'est le plus proche du pouce — la barre du bas, ou le premier écran.</p>\n\n<p>Placez-la à côté d\'une application que vous ouvrez chaque matin. C\'est le principe de l\'ancrage : votre habitude nouvelle s\'accroche à une habitude existante, et n\'a plus besoin de volonté pour se déclencher.</p>\n\n<h2>Une alarme, si l\'ancrage ne suffit pas</h2>\n\n<p>Si vous oubliez malgré tout, posez une alarme à une heure où vous êtes réellement disponible.</p>\n\n<p>Évitez le soir tard : c\'est le moment où l\'on remet au lendemain, et où les séries se cassent. Le matin, ou en début d\'après-midi, fonctionne nettement mieux.</p>\n\n<h2>Ce que ça change réellement</h2>\n\n<p>Soyons mesurés : ce raccourci ne fait pas gagner de coins. Il fait gagner du temps et supprime des occasions d\'abandonner.</p>\n\n<p>Or sur une plateforme où les délais d\'attente empêchent de rattraper les jours manqués, la constance vaut plus que n\'importe quelle optimisation. Tout ce qui rend la session plus facile à commencer protège directement vos gains.</p>\n','📱','Équipe Wintaskly','Un raccourci sur l\'écran d\'accueil pour gagner 30 secondes par jour','Trente secondes par jour font trois heures par an. Et le détail que presque tout le monde manque.','published',5,'2026-10-29 07:00:00'
 WHERE NOT EXISTS (SELECT 1 FROM (SELECT 1) x WHERE EXISTS (SELECT 1 FROM `blog_posts` WHERE `slug`='raccourci-ecran-accueil'));

